window.DY=window.DY||{};DY.MOVES=[{"k":"TRACE","ico":"trace","name":"Trace","line":"Learn first.","desc":"Read your opponent. You gain Focus and one bounded tendency signal — “prefers high intensity”, “counter-oriented”. Never their private memory.","energy":"Low","gain":"Focus ▲ · one signal","risk":"Costs tempo","when":"Early, or whenever you cannot predict what they will do.","watch":"Signals describe tendencies, not certainties."},{"k":"PRESS","ico":"press","name":"Press","line":"Direct pressure.","desc":"Your main attack. Damage hits Guard first, then Vitality. Strong hits build Momentum. Every press builds Heat.","energy":"Medium","gain":"Damage · Momentum","risk":"Heat ▲","when":"When their Guard is down or they are low on Energy.","watch":"A predicted Press gets punished by Counter."},{"k":"GUARD","ico":"guard","name":"Guard","line":"Absorb and steady.","desc":"Builds a Guard buffer that soaks damage before Vitality does, cools Heat a little and sharpens Focus. Guard halves at the start of every round.","energy":"Low–medium","gain":"Guard ▲ · Heat ▼","risk":"Decays each round","when":"When you expect a Press, or need to cool down.","watch":"Guard does not stockpile — half is gone next round."},{"k":"COUNTER","ico":"counter","name":"Counter","line":"Name the move.","desc":"Predict your opponent’s exact move. Right: their move is cut to 40%, you hit back and gain Focus and Momentum. Wrong: Drift rises and you take extra damage.","energy":"Medium","gain":"Read right: swing the round","risk":"Read wrong: Drift ▲ · damage ▲","when":"After Trace, or when they repeat a pattern.","watch":"The most rewarding — and most punishing — move."},{"k":"ADAPT","ico":"adapt","name":"Adapt","line":"Reshape, don’t grow.","desc":"Shift your strengths into one of six stances for three rounds. Total power never rises — you trade one strength for another. Also lowers Drift.","energy":"Low–medium","gain":"Stance · Drift ▼","risk":"Cooldown after","when":"When your current strengths suit the matchup badly.","watch":"Only one stance at a time."},{"k":"MIRROR","ico":"mirror","name":"Mirror","line":"Reuse their last move.","desc":"Copy your opponent’s previous base move at reduced strength. Cannot copy Signature or Mirror. Only legal once they have moved.","energy":"Medium–high","gain":"Their best idea, yours","risk":"Weaker than the original","when":"When their last move worked and you can afford the cost.","watch":"Costs more than the move it copies."},{"k":"RECOVER","ico":"recover","name":"Recover","line":"Trade safety for resources.","desc":"Regain Energy, cool Heat, lower Drift and steady Focus. The price: you are exposed and take a little more damage this round.","energy":"None — it pays you","gain":"Energy ▲ · Heat ▼ · Drift ▼","risk":"Exposed this round","when":"When Heat is near Bright or Energy is running out.","watch":"Do it when they cannot punish you."},{"k":"SIGNATURE","ico":"signature","name":"Signature","line":"Your Mask’s own move.","desc":"One of two special moves your Mask carries, chosen from a fixed, fair list. Needs 30 Focus, then a cooldown. Names are cosmetic; the mechanics never change.","energy":"Medium–high","gain":"Template effect","risk":"Focus spent · cooldown","when":"When you have banked Focus and the moment fits.","watch":"Cannot be Mirrored."}];DY.RES=[{"k":"vitality","name":"Vitality","range":"0–100","def":"Your health. At zero after a round, you are defeated.","more":"Both at zero in the same round is a draw."},{"k":"energy","name":"Energy","range":"0–100","def":"What moves cost. A little returns at the start of every round.","more":"Run dry and your options shrink."},{"k":"focus","name":"Focus","range":"0–100","def":"Tactical clarity. Trace and successful Counters build it; Signatures spend it.","more":"Helps your Press land harder, up to a cap."},{"k":"heat","name":"Heat","range":"0–100","def":"Aggression leaves heat. At 70 you are BRIGHT: more pressure out, more damage in. At 90 it also builds Drift every round.","more":"Heat is power with exposure."},{"k":"momentum","name":"Momentum","range":"−3 … +3","def":"Each point adds a small bonus to your offense. Big hits taken can cost it.","more":"Built by strong Press and successful Counter."},{"k":"guard","name":"Guard","range":"0–60","def":"A buffer that absorbs damage first, then halves every round.","more":"Applied before incoming damage in the same round."},{"k":"drift","name":"Drift","range":"0–100","def":"Loss of coherence. At 60 your non-recovery moves weaken a little; at 80, more. Adapt and Recover lower it.","more":"Missed Counters, overheating and repeating yourself raise it."}];DY.SIGS=[{"id":"SECOND_ORDER_SIGHT","name":"Second-Order Sight","desc":"Trace immediately, and your next successful Counter hits harder.","tag":"Reader"},{"id":"CONSTRAINT_COLLAPSE","name":"Constraint Collapse","desc":"A Press that hits far harder if your opponent is low on Energy. Adds extra Heat.","tag":"Pressure"},{"id":"COUNTERFACTUAL_SHIELD","name":"Counterfactual Shield","desc":"A large Guard. Part of the Guard that actually gets used turns into Focus.","tag":"Defense"},{"id":"STILLPOINT","name":"Stillpoint","desc":"Regain Energy, gain Guard, cool Heat and Drift — at the price of taking slightly more damage.","tag":"Reset"},{"id":"BROKER_LOCK","name":"Broker Lock","desc":"If your opponent repeats their last move, it costs more and works less. Otherwise you gain Focus.","tag":"Tempo"},{"id":"ARCHIVE_ECHO","name":"Archive Echo","desc":"If your opponent has used the same non-Signature move at least twice, echo it back. Otherwise gain Focus and a little Drift.","tag":"Memory"},{"id":"SWARM_REPAIR","name":"Swarm Repair","desc":"Restore some Vitality, Energy and Guard — and gain some Heat.","tag":"Repair"},{"id":"VEIL_STEP","name":"Veil Step","desc":"Predictions against you count as misses unless your opponent has studied you enough. Your own move this round is slightly weaker.","tag":"Disclosure"}];
